  return t;
}

function arrow(g, x1, y1, x2, y2, color, w) {
  var dx = x2 - x1, dy = y2 - y1, len = Math.hypot(dx, dy);
  if (len < 2) return null;
  var ux = dx / len, uy = dy / len;
  var hl = Math.min(15, Math.max(6, len * 0.30));
  var hw = hl * 0.58;
  var bx = x2 - ux * hl, by = y2 - uy * hl;
  var grp = g.group();
  grp.line(x1, y1, bx, by).stroke({ color: color, width: w, linecap: 'round' });
  grp.polygon([[x2, y2], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]]
    .map(function (p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' ')).fill(color);
  return grp;
}

function arcPoly(g, cx, cy, r, a1, a2, opts) {
  var n = 40, pts = [];
  for (var i = 0; i <= n; i++) {
    var a = a1 + (a2 - a1) * i / n;
    pts.push((cx + r * Math.sin(a)).toFixed(2) + ',' + (cy + r * Math.cos(a)).toFixed(2));
  }
  var p = g.polyline(pts.join(' ')).fill('none')
    .stroke({ color: opts.color || INK, width: opts.width || 1.4, linecap: 'round' });
  if (opts.dash) p.attr('stroke-dasharray', opts.dash);
  return p;
}

function interactive(el, tip, title, body) {
  if (!el) return;
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
}

function placeTipLabel(g, bob, dir, len, minLen, str, color, size) {
  var d = Math.max(len, minLen) + 16;
  var lx = bob.x + dir.x * d, ly = bob.y + dir.y * d;
  var anchor = dir.x >= 0 ? 'start' : 'end';
  lx += (anchor === 'start' ? 8 : -8);
  ly += 4;
  var wEst = str.length * size * 0.50;
  if (anchor === 'end' && lx - wEst < 8) { anchor = 'start'; lx = Math.max(10, lx); }
  if (anchor === 'start' && lx + wEst > W - 8) { anchor = 'end'; lx = Math.min(W - 10, lx); }
  ly = Math.max(40, Math.min(H - 76, ly));
  // leader line when arrow tip is far from the label
  var tipx = bob.x + dir.x * len, tipy = bob.y + dir.y * len;
  if (Math.hypot(lx - tipx, ly - tipy) > 26) {
    g.line(tipx, tipy, lx + (anchor === 'start' ? -4 : 4), ly - 4)
      .stroke({ color: '#b8b8b8', width: 0.8, dasharray: '2,3' });
  }
  return txt(g, lx, ly, str, { anchor: anchor, color: color, size: size });
}

/* ---------- main render ---------- */
function render() {
  gDyn.clear();
  var thDeg = state.theta, th = thDeg * Math.PI / 180;
  var s = Math.sin(th), c = Math.cos(th), sg = (th >= 0 ? 1 : -1);
  var bob = { x: PX + L * s, y: PY + L * c };

  var radDir = { x: s, y: c };            // along string, away from pivot
  var tenDir = { x: -s, y: -c };          // +y : toward pivot
  var xDir = { x: c, y: -s };             // +x : tangent, away from equilibrium
  var tanDir = { x: -sg * c, y: sg * s }; // restoring tangential direction

  var tanLen = WLEN * Math.abs(s);
  var radLen = WLEN * c;
  var tenLen = WLEN * c;
  var linLen = WLEN * Math.abs(th);

  /* geometry */
  gDyn.line(PX, PY, PX, PY + L + 14).stroke({ color: '#2a2a2a', width: 1.7, dasharray: '7,5' });
  gDyn.circle(5).center(PX, PY).fill(INK);

  if (Math.abs(th) > 0.03) {
    var arcS = arcPoly(gDyn, PX, PY, L, 0, th, { color: '#2a2a2a', width: 1.8, dash: '8,5' });
    interactive(arcS, 's = Lθ — arc-length displacement from equilibrium',
      'Arc displacement s',
      'The bob moves along an arc of radius L, so its displacement from equilibrium is s = Lθ. The restoring force acts along this arc, tangent to the path.');
  }
  if (Math.abs(thDeg) > 8) {
    arcPoly(gDyn, PX, PY, 42, 0, th, { color: INK, width: 1.2 });
    txt(gDyn, PX + 54 * Math.sin(th / 2), PY + 54 * Math.cos(th / 2), '\u03b8', { italic: true, size: 15 });
    txt(gDyn, PX + (L - 24) * Math.sin(th * 0.5), PY + (L - 24) * Math.cos(th * 0.5), 's',
      { italic: true, size: 14 });
  }

  var strLine = gDyn.line(PX, PY, bob.x, bob.y).stroke({ color: INK, width: 2 });
  interactive(strLine, 'String of length L', 'The string',
    'The string is inextensible, so the bob is constrained to a circular arc of radius L. The string can only pull along its own direction — that is why it cancels the radial part of gravity but nothing else.');
  txt(gDyn, bob.x * 0 + PX + 0.45 * L * s + 18 * sg * c,
    PY + 0.45 * L * c - 18 * sg * s, 'L', { italic: true, size: 15 });

  /* construction parallelogram */
  var wTip = { x: bob.x, y: bob.y + WLEN };
  if (tanLen > 6 && radLen > 6) {
    var rTip = { x: bob.x + radDir.x * radLen, y: bob.y + radDir.y * radLen };
    var tTip = { x: bob.x + tanDir.x * tanLen, y: bob.y + tanDir.y * tanLen };
    gDyn.line(rTip.x, rTip.y, wTip.x, wTip.y).stroke({ color: GRAY, width: 0.9, dasharray: '4,4' });
    gDyn.line(tTip.x, tTip.y, wTip.x, wTip.y).stroke({ color: GRAY, width: 0.9, dasharray: '4,4' });
  }

  /* arrows */
  var aTen = arrow(gDyn, bob.x, bob.y, bob.x + tenDir.x * tenLen, bob.y + tenDir.y * tenLen, NAVY, 3.4);
  interactive(aTen, 'F_T = mg cos θ — tension, along the string toward the pivot',
    'Tension F\u1D1B',
    'The string pulls the bob toward the pivot with exactly the force needed to cancel the radial component of gravity, F_T = mg cos θ. Tension does no work and cannot push the bob back toward equilibrium.');

  var aRad = arrow(gDyn, bob.x, bob.y, bob.x + radDir.x * radLen, bob.y + radDir.y * radLen, CRIM, 3.2);
  interactive(aRad, '\u2212mg cos θ — radial component, cancelled by tension',
    'Radial component \u2212mg cos\u2009θ',
    'This piece of the weight lies along the string, pointing away from the pivot. Tension exactly balances it, so it produces no acceleration along the arc — it only keeps the string taut.');

  if (state.model === 'exact' || state.model === 'both') {
    var aTan = arrow(gDyn, bob.x, bob.y, bob.x + tanDir.x * tanLen, bob.y + tanDir.y * tanLen, CRIM, 3.4);
    interactive(aTan, '\u2212mg sin θ — the unbalanced restoring force',
      'Restoring force \u2212mg sin\u2009\u03b8',
      'Nothing balances the tangential part of the weight, so this is the net force on the bob. The minus sign means it always points back toward the hanging position, which is what makes the motion oscillate.');
  }
  if (state.model === 'small' || state.model === 'both') {
    var off = (state.model === 'both') ? 10 : 0;
    var ox = bob.x + radDir.x * off, oy = bob.y + radDir.y * off;
    var aLin = arrow(gDyn, ox, oy, ox + tanDir.x * linLen, oy + tanDir.y * linLen, ORANGE, 3.2);
    interactive(aLin, '\u2212mgθ — linear (small-angle) approximation',
      'Small-angle approximation',
      'Replacing sin θ by θ makes the restoring force −mgθ, exactly proportional to the displacement s = Lθ. That is Hooke\u2019s law form, so the pendulum becomes a simple harmonic oscillator with T = 2π√(L/g).');
    if (state.model === 'both' && Math.abs(linLen - tanLen) > 5) {
      var e1 = { x: bob.x + tanDir.x * tanLen, y: bob.y + tanDir.y * tanLen };
      var e2 = { x: ox + tanDir.x * linLen, y: oy + tanDir.y * linLen };
      gDyn.line(e1.x, e1.y, e2.x, e2.y).stroke({ color: '#777', width: 1, dasharray: '3,3' });
      txt(gDyn, (e1.x + e2.x) / 2 + tanDir.x * 12, (e1.y + e2.y) / 2 + tanDir.y * 12 + 6,
        '\u0394', { size: 12, color: '#555' });
    }
  }

  var aW = arrow(gDyn, bob.x, bob.y, wTip.x, wTip.y, CRIM, 3.4);
  interactive(aW, 'w = mg — the weight, constant and always vertical',
    'Weight w = mg',
    'Gravity on the bob never changes in size or direction. Everything interesting comes from resolving this one constant vector into a component along the string and a component tangent to the arc.');

  /* angle between weight and radial arrow, at the bob */
  if (Math.abs(thDeg) > 8 && radLen > 24) {
    arcPoly(gDyn, bob.x, bob.y, 30, 0, th, { color: INK, width: 1.1 });
    txt(gDyn, bob.x + 41 * Math.sin(th / 2), bob.y + 41 * Math.cos(th / 2), '\u03b8',
