  interactive(bobEl, 'Bob of mass m', 'The bob',
    'The whole mass m is treated as a point at the end of the string. Its acceleration along the arc is a = −g sin θ, independent of m — the mass cancels out of the equation of motion.');
  txt(gDyn, bob.x + sg * 22, bob.y - 9, 'm', { italic: true, size: 15, anchor: sg > 0 ? 'start' : 'end' });

  /* force labels */
  if (tenLen > 20) {
