  txt(rg, 374, 384, '\u03b8 = ' + thDeg.toFixed(0) + '\u00b0 = ' + rad.toFixed(3) + ' rad',
    { anchor: 'start', size: 10.5, halo: 0, color: '#222' });
  txt(rg, 374, 400, 'sin \u03b8 = ' + sinv.toFixed(3) + '  \u2192  |F| = ' + Math.abs(sinv).toFixed(2) + ' mg',
    { anchor: 'start', size: 10.5, halo: 0, color: CRIM });
  if (state.model !== 'exact') {
    var err = Math.abs(sinv) < 1e-6 ? 0 : (Math.abs(rad) - Math.abs(sinv)) / Math.abs(sinv) * 100;
    txt(rg, 374, 416, '\u03b8 (rad) = ' + Math.abs(rad).toFixed(3) + '  \u2192  error ' + err.toFixed(1) + '%',
      { anchor: 'start', size: 10.5, halo: 0, color: ORANGE });
  }

  updateReadoutPanel(thDeg, sinv, rad);
}

function updateReadoutPanel(thDeg, sinv, rad) {
  var el = document.getElementById('readout');
  if (!el) return;
  var err = Math.abs(sinv) < 1e-6 ? 0 : (Math.abs(rad) - Math.abs(sinv)) / Math.abs(sinv) * 100;
  var lines = [
    '\u03b8      = ' + thDeg.toFixed(0) + '\u00b0 (' + rad.toFixed(3) + ' rad)',
    'sin\u03b8   = ' + sinv.toFixed(3),
    'F_tan  = ' + (-sinv).toFixed(3) + ' mg',
    'F_rad  = ' + (-Math.cos(rad)).toFixed(3) + ' mg'
  ];
  if (state.model !== 'exact') lines.push('\u03b8 vs sin\u03b8 error = ' + err.toFixed(1) + '%');
  el.textContent = lines.join('\n');
  el.style.whiteSpace = 'pre';
}

/* ---------- interactions ---------- */
function update_thetaSlider(v) {
  stopSwing();
  state.theta = v;
  render();
}

function toggle_forceModel(v) {
  state.model = v;
  render();
}

function startSwing() {
  if (state.running) return;
  state.thRad = state.theta * Math.PI / 180;
  if (Math.abs(state.thRad) < 0.05) state.thRad = 25 * Math.PI / 180;
  state.omega = 0;
  state.running = true;
  document.getElementById('swingBtn').textContent = '\u23F8 Pause';
  lastT = 0;
  requestAnimationFrame(frame);
}

function stopSwing() {
  if (!state.running) return;
  state.running = false;
  document.getElementById('swingBtn').textContent = '\u25B6 Release the pendulum';
}

function trigger_swing() {
  if (state.running) { stopSwing(); render(); }
  else { startSwing(); }
}

var lastT = 0;
function frame(ts) {
  if (!state.running) return;
  if (!lastT) lastT = ts;
  var dt = Math.min(0.04, (ts - lastT) / 1000);
  lastT = ts;
  var n = 6, h = dt / n;
  for (var i = 0; i < n; i++) {
    state.omega += -G_OVER_L * Math.sin(state.thRad) * h;
    state.thRad += state.omega * h;
  }
  state.theta = state.thRad * 180 / Math.PI;
  var inp = document.getElementById('thetaSliderInput');
  inp.value = Math.round(state.theta);
  document.getElementById('thetaSliderVal').value = Math.round(state.theta);
  render();
  requestAnimationFrame(frame);
}

/* ---------- demo steps ---------- */
var steps = [
  {
    t: 'The pendulum at rest',
    n: 'At \u03b8 = 0 the bob hangs on the dashed vertical. The weight w = mg points straight down along the string and is entirely balanced by the tension F_T \u2014 there is no tangential force, so nothing accelerates the bob.',
    theta: 0, model: 'exact', swing: false
  },
  {
    t: 'Displace the bob and split the weight',
    n: 'Drag \u03b8 out to 25\u00b0. The weight now splits into \u2212mg cos \u03b8 along the string (opposed by tension) and \u2212mg sin \u03b8 tangent to the arc. Only the tangential piece is unbalanced, and it points back toward equilibrium along \u2212x.',
    theta: 25, model: 'exact', swing: false
  },
  {
    t: 'Push to a large angle',
    n: 'At 60\u00b0 the tangential arrow is long and the radial arrow has shrunk. Notice the restoring force grows with displacement \u2014 but not in proportion to it, because it follows sin \u03b8, not \u03b8.',
    theta: 60, model: 'exact', swing: false
  },
  {
    t: 'Sign flip through equilibrium',
    n: 'Release the bob and watch. Each time it crosses the dashed vertical the tangential arrow reverses direction, so the force always points back toward the center \u2014 this is what sustains the oscillation.',
    theta: 25, model: 'exact', swing: true
  },
  {
    t: 'The small-angle approximation',
    n: 'Switch to the compare view. Below about 15\u00b0 the \u2212mg\u03b8 arrow overlaps the \u2212mg sin \u03b8 arrow almost exactly: the restoring force is proportional to displacement, so the pendulum is a simple harmonic oscillator with period T = 2\u03c0\u221a(L/g).',
    theta: 12, model: 'both', swing: false
  },
  {
    t: 'Where the approximation breaks',
    n: 'Push \u03b8 back out to 50\u00b0 with both models drawn. The two arrows now visibly disagree \u2014 the true restoring force is weaker than the linear estimate, the motion is no longer simple harmonic, and the period lengthens.',
    theta: 50, model: 'both', swing: false
  }
];
var curStep = 1;

function applyStep(i) {
  curStep = (i + steps.length) % steps.length;
  var st = steps[curStep];
  stopSwing();
  document.getElementById('thetaSliderInput').value = st.theta;
  document.getElementById('thetaSliderVal').value = st.theta;
  state.theta = st.theta;
  document.getElementById('forceModelInput').value = st.model;
  state.model = st.model;
  document.getElementById('demoTitle').textContent = st.t;
  document.getElementById('demoNarration').textContent = st.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' / ' + steps.length;
  if (st.swing) startSwing(); else render();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

/* ---------- boot: default view matches the source figure (\u03b8 = 25\u00b0) ---------- */
applyStep(1);
render();
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A pendulum's weight resolves into a component along the string (balanced by tension) and a tangential component −mg sin θ that always points back toward equilibrium, acting as the restoring force that drives oscillation.
KEY INSIGHT (what students should walk away understanding): Tension cancels only the radial part of gravity; the leftover tangential part, −mg sin θ, always points back toward the hanging position — and when θ is small enough that sin θ ≈ θ, that restoring force becomes proportional to displacement, which is exactly the definition of simple harmonic motion.
DEMO STEPS: 6 guided steps — implement the step player in #ui

