  <select id="forceModelInput" onchange="toggle_forceModel(this.value)">
    <option value="exact">Exact: −mg sin θ</option>
    <option value="small">Small-angle: −mg θ</option>
    <option value="both">Compare both</option>
  </select></label>
<label style="flex-direction:row;align-items:center;gap:6px">
  <input id="showConstructionInput" type="checkbox" onchange="toggle_showConstruction(this.checked)">
  Show weight-decomposition construction</label>
<button id="swingBtn" onclick="trigger_swing()">▶ Release the pendulum</button>
<span style="font-weight:600;font-size:11px;margin-top:4px">Colour key</span>
<span style="display:flex;align-items:center;gap:7px;font-size:12px"><span style="display:inline-block;width:20px;height:4px;border-radius:2px;background:#1b4f72"></span>tension F<sub>T</sub> (along string)</span>
<span style="display:flex;align-items:center;gap:7px;font-size:12px"><span style="display:inline-block;width:20px;height:4px;border-radius:2px;background:#cf3b41"></span>weight mg and its components</span>
<span id="legendLinear" style="display:none;align-items:center;gap:7px;font-size:12px"><span style="display:inline-block;width:20px;height:4px;border-radius:2px;background:#e08a1e"></span>linear estimate −mgθ</span>
<span style="font-weight:600;font-size:11px;margin-top:4px">Numbers</span>
<span id="readout" style="font-size:12px;line-height:1.55;color:#222;font-family:ui-monospace,Consolas,monospace;white-space:pre"></span>
<span style="font-size:10px;color:#666;line-height:1.4">Hover or click any arrow for an explanation.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var W = 440, H = 430;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var PX = 178, PY = 30, L = 195, WLEN = 95, BOBR = 14, CEIL_H = 24;
var NAVY = '#1b4f72', CRIM = '#cf3b41', ORANGE = '#e08a1e', INK = '#141414', GRAY = '#9a9a9a';

var state = { theta: 25, model: 'exact', constr: false, running: false, thRad: 0, omega: 0 };
var G_OVER_L = 4.0;

/* ---------- static background ---------- */
var ceilGrad = draw.gradient('linear', function (add) {
  add.stop(0, '#eacf9f'); add.stop(1, '#f8ecd8');
}).from(0, 0).to(0, 1);
draw.rect(W, CEIL_H).move(0, 0).fill(ceilGrad);
draw.line(0, CEIL_H, W, CEIL_H).stroke({ color: '#d8c49a', width: 1 });

var bobGrad = draw.gradient('radial', function (add) {
  add.stop(0, '#ffffff'); add.stop(0.45, '#d5d5d5'); add.stop(1, '#7c7c7c');
}).attr({ cx: 0.36, cy: 0.30, r: 0.75 });

var gDyn = draw.group();

/* ---------- helpers ---------- */
function txt(g, x, y, str, o) {
  o = o || {};
  var t = g.plain(str);
  t.font({
    family: 'Georgia, "Times New Roman", serif',
    size: o.size || 14,
    style: o.italic ? 'italic' : 'normal',
    weight: o.weight || 'normal'
  });
  t.attr({
    x: x, y: y, 'text-anchor': o.anchor || 'middle', 'dominant-baseline': 'middle',
    fill: o.color || INK, 'paint-order': 'stroke', stroke: '#fff',
    'stroke-width': (o.halo == null ? 3.4 : o.halo), 'stroke-linejoin': 'round'
  });
  return t;
}

/* single text node with a real subscript tspan (e.g. F_T) */
function subTxt(g, x, y, main, sub, o) {
  o = o || {};
  var size = o.size || 15;
  var t = g.text(function (add) {
    add.tspan(main);
    add.tspan(sub).attr({ 'baseline-shift': 'sub', 'font-size': (size * 0.68).toFixed(1) });
  });
  t.font({ family: 'Georgia, "Times New Roman", serif', size: size, style: 'italic' });
  t.attr({
    x: x, y: y, 'text-anchor': o.anchor || 'middle', 'dominant-baseline': 'middle',
    fill: o.color || INK, 'paint-order': 'stroke', stroke: '#fff',
    'stroke-width': 3.4, 'stroke-linejoin': 'round'
  });
  return t;
}

function arrow(g, x1, y1, x2, y2, color, w) {
  var dx = x2 - x1, dy = y2 - y1, len = Math.hypot(dx, dy);
  if (len < 2) return null;
  var ux = dx / len, uy = dy / len;
  var hl = Math.min(16, Math.max(6, len * 0.30));
  var hw = hl * 0.58;
  var bx = x2 - ux * hl, by = y2 - uy * hl;
  var grp = g.group();
  grp.line(x1, y1, bx, by).stroke({ color: color, width: w, linecap: 'round' });
  grp.polygon([[x2, y2], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]]
    .map(function (p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' ')).fill(color);
  return grp;
}

function arcPoly(g, cx, cy, r, a1, a2, opts) {
  var n = 40, pts = [];
  for (var i = 0; i <= n; i++) {
    var a = a1 + (a2 - a1) * i / n;
    pts.push((cx + r * Math.sin(a)).toFixed(2) + ',' + (cy + r * Math.cos(a)).toFixed(2));
  }
  var p = g.polyline(pts.join(' ')).fill('none')
    .stroke({ color: opts.color || INK, width: opts.width || 1.4, linecap: 'round' });
  if (opts.dash) p.attr('stroke-dasharray', opts.dash);
  return p;
}

function interactive(el, tip, title, body) {
  if (!el) return;
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
}

/* label sits just beyond the arrow tip — no leader lines */
function placeTipLabel(g, bob, dir, len, minLen, str, color, size) {
  var d = Math.max(len, minLen) + 10;
  var lx = bob.x + dir.x * d, ly = bob.y + dir.y * d;
  var anchor = dir.x >= 0 ? 'start' : 'end';
  lx += (anchor === 'start' ? 7 : -7);
  ly += 5;
  var wEst = str.length * size * 0.50;
  if (anchor === 'end' && lx - wEst < 6) { anchor = 'start'; lx = Math.max(8, lx); }
  if (anchor === 'start' && lx + wEst > W - 6) { anchor = 'end'; lx = Math.min(W - 8, lx); }
  ly = Math.max(CEIL_H + 14, Math.min(H - 16, ly));
  return txt(g, lx, ly, str, { anchor: anchor, color: color, size: size });
}

/* ---------- main render ---------- */
function render() {
  gDyn.clear();
  var thDeg = state.theta, th = thDeg * Math.PI / 180;
  var s = Math.sin(th), c = Math.cos(th), sg = (th >= 0 ? 1 : -1);
  var bob = { x: PX + L * s, y: PY + L * c };

  var radDir = { x: s, y: c };            // along string, away from pivot
  var tenDir = { x: -s, y: -c };          // +y : toward pivot
  var xDir = { x: c, y: -s };             // +x : tangent, away from equilibrium
  var tanDir = { x: -sg * c, y: sg * s }; // restoring tangential direction

  var tanLen = WLEN * Math.abs(s);
  var radLen = WLEN * c;
  var tenLen = WLEN * c;
  var linLen = WLEN * Math.abs(th);

  /* geometry */
  gDyn.line(PX, PY, PX, PY + L + 16).stroke({ color: '#2a2a2a', width: 1.7, dasharray: '7,5' });
  gDyn.circle(5).center(PX, PY).fill(INK);

  if (Math.abs(th) > 0.03) {
    var arcS = arcPoly(gDyn, PX, PY, L, 0, th, { color: '#2a2a2a', width: 1.8, dash: '8,5' });
    interactive(arcS, 's = Lθ — arc-length displacement from equilibrium',
      'Arc displacement s',
      'The bob is constrained to a circular arc of radius L, so its displacement from equilibrium is the arc length s = Lθ. The restoring force acts along this arc, tangent to the path.');
  }
  if (Math.abs(thDeg) > 8) {
    arcPoly(gDyn, PX, PY, 44, 0, th, { color: INK, width: 1.2 });
    txt(gDyn, PX + 57 * Math.sin(th / 2), PY + 57 * Math.cos(th / 2), '\u03b8', { italic: true, size: 15 });
    txt(gDyn, PX + (L - 32) * Math.sin(th * 0.5), PY + (L - 32) * Math.cos(th * 0.5), 's',
      { italic: true, size: 15 });
  }

  var strLine = gDyn.line(PX, PY, bob.x, bob.y).stroke({ color: INK, width: 2 });
  interactive(strLine, 'String of length L', 'The string',
    'The string is inextensible, so the bob can only move on a circular arc of radius L. It can pull only along its own direction — that is why it cancels the radial part of gravity and nothing else.');
  txt(gDyn, PX + 0.45 * L * s + 18 * sg * c, PY + 0.45 * L * c - 18 * sg * s,
    'L', { italic: true, size: 16 });

  /* optional decomposition construction (off by default) */
  var wTip = { x: bob.x, y: bob.y + WLEN };
  if (state.constr && tanLen > 6 && radLen > 6) {
    var rTip = { x: bob.x + radDir.x * radLen, y: bob.y + radDir.y * radLen };
    var tTip = { x: bob.x + tanDir.x * tanLen, y: bob.y + tanDir.y * tanLen };
    var cg = gDyn.group();
    cg.line(rTip.x, rTip.y, wTip.x, wTip.y).stroke({ color: GRAY, width: 1, dasharray: '4,4' });
    cg.line(tTip.x, tTip.y, wTip.x, wTip.y).stroke({ color: GRAY, width: 1, dasharray: '4,4' });
    interactive(cg, 'Parallelogram: the two components add back up to w = mg',
      'Vector decomposition',
      'The radial and tangential arrows are the two sides of a parallelogram whose diagonal is the weight itself. Adding them back together returns exactly w = mg, so nothing has been added or lost by resolving the vector.');
  }

  /* arrows */
  var aTen = arrow(gDyn, bob.x, bob.y, bob.x + tenDir.x * tenLen, bob.y + tenDir.y * tenLen, NAVY, 3.4);
  interactive(aTen, 'F_T = mg cos \u03b8 + mv\u00b2/L — string tension, toward the pivot',
    'Tension F\u1D1B',
    'The string pulls the bob toward the pivot. It must both balance the radial weight component and supply the centripetal force for the circular path: F_T = mg cos \u03b8 + mv\u00b2/L. Only at the turning points, where v = 0, does it reduce to mg cos \u03b8. Tension is always perpendicular to the motion, so it does no work and can never push the bob back toward equilibrium.');

  var aRad = arrow(gDyn, bob.x, bob.y, bob.x + radDir.x * radLen, bob.y + radDir.y * radLen, CRIM, 3.2);
  interactive(aRad, '\u2212mg cos \u03b8 — radial component of the weight, along the string',
    'Radial component \u2212mg cos\u2009\u03b8',
    'This part of the weight lies along the string, pointing away from the pivot. The string答s tension handles it, so it produces no acceleration along the arc — it only keeps the string taut and bends the path into a circle.');

  if (state.model === 'exact' || state.model === 'both') {
    var aTan = arrow(gDyn, bob.x, bob.y, bob.x + tanDir.x * tanLen, bob.y + tanDir.y * tanLen, CRIM, 3.4);
    interactive(aTan, '\u2212mg sin \u03b8 — the unbalanced restoring force',
      'Restoring force \u2212mg sin\u2009\u03b8',
      'Nothing balances the tangential part of the weight, so this is the net force along the arc. The minus sign means it always points back toward the hanging position, which is exactly what makes the motion oscillate: ma = \u2212mg sin \u03b8.');
  }
  if (state.model === 'small' || state.model === 'both') {
    var off = (state.model === 'both') ? 11 : 0;
    var ox = bob.x + radDir.x * off, oy = bob.y + radDir.y * off;
    var aLin = arrow(gDyn, ox, oy, ox + tanDir.x * linLen, oy + tanDir.y * linLen, ORANGE, 3.2);
    interactive(aLin, '\u2212mg\u03b8 — linear (small-angle) estimate of the restoring force',
      'Small-angle approximation',
      'Replacing sin \u03b8 by \u03b8 (in radians) makes the restoring force \u2212mg\u03b8 = \u2212(mg/L)s, exactly proportional to displacement. That is Hooke\u2019s law form, so the pendulum becomes a simple harmonic oscillator with period T = 2\u03c0\u221a(L/g).');
    if (state.model === 'both' && Math.abs(linLen - tanLen) > 5) {
      var e1 = { x: bob.x + tanDir.x * tanLen, y: bob.y + tanDir.y * tanLen };
      var e2 = { x: ox + tanDir.x * linLen, y: oy + tanDir.y * linLen };
      gDyn.line(e1.x, e1.y, e2.x, e2.y).stroke({ color: '#8a8a8a', width: 1, dasharray: '3,3' });
    }
  }

  var aW = arrow(gDyn, bob.x, bob.y, wTip.x, wTip.y, CRIM, 3.4);
  interactive(aW, 'w = mg — the weight, constant in size and always vertical',
    'Weight w = mg',
    'Gravity on the bob never changes in magnitude or direction. Everything interesting comes from resolving this one constant vector into a piece along the string and a piece tangent to the arc.');

  /* angle between weight and radial arrow, at the bob */
  if (Math.abs(thDeg) > 8 && radLen > 26) {
    arcPoly(gDyn, bob.x, bob.y, 31, 0, th, { color: INK, width: 1.1 });
    txt(gDyn, bob.x + 43 * Math.sin(th / 2), bob.y + 43 * Math.cos(th / 2), '\u03b8',
      { italic: true, size: 14 });
  }

  /* bob drawn over the arrow tails */
  var bobEl = gDyn.circle(BOBR * 2).center(bob.x, bob.y).fill(bobGrad)
    .stroke({ color: '#5f5f5f', width: 0.8 });
  interactive(bobEl, 'Bob of mass m', 'The bob',
    'The whole mass m is idealised as a point at the end of the string. Its acceleration along the arc is a = \u2212g sin \u03b8, independent of m — the mass cancels out of the equation of motion, so heavy and light bobs swing identically.');
  txt(gDyn, bob.x + sg * 23, bob.y - 10, 'm', { italic: true, size: 16, anchor: sg > 0 ? 'start' : 'end' });

  /* force labels */
  if (tenLen > 22) {
    var mx = bob.x + tenDir.x * tenLen * 0.55, my = bob.y + tenDir.y * tenLen * 0.55;
    var flx = mx + sg * 24 * c, fly = my - sg * 24 * s;
    subTxt(gDyn, flx, fly, 'F', 'T', { size: 16, color: NAVY, anchor: 'middle' });
  }
  txt(gDyn, bob.x, bob.y + WLEN + 22, 'w = mg', { italic: true, size: 15, color: CRIM });
  if (radLen > 14) placeTipLabel(gDyn, bob, radDir, radLen, 34, '\u2212mg cos \u03b8', CRIM, 14);
  if (tanLen > 12 && (state.model === 'exact' || state.model === 'both')) {
    placeTipLabel(gDyn, bob, tanDir, tanLen, 38, '\u2212mg sin \u03b8', CRIM, 14);
  }
  if (linLen > 12 && state.model === 'small') {
    placeTipLabel(gDyn, bob, tanDir, linLen, 38, '\u2212mg \u03b8', ORANGE, 14);
  }
  if (state.model === 'both' && linLen > 12) {
    var lo = bob.x + radDir.x * 11, loy = bob.y + radDir.y * 11;
    var lpx = lo + tanDir.x * (linLen + 14), lpy = loy + tanDir.y * (linLen + 14);
    txt(gDyn, lpx, lpy + (sg > 0 ? 16 : 16), '\u2212mg \u03b8',
      { anchor: sg > 0 ? 'end' : 'start', color: ORANGE, size: 13, italic: true });
  }

  /* local axes, upper right */
  var AX = 372, AY = 178, AR = 38, BK = 22;
  var axg = gDyn.group();
  axg.line(AX - tenDir.x * BK, AY - tenDir.y * BK, AX + tenDir.x * (AR - 10), AY + tenDir.y * (AR - 10))
    .stroke({ color: INK, width: 0.9 });
  arrow(axg, AX + tenDir.x * (AR - 12), AY + tenDir.y * (AR - 12), AX + tenDir.x * AR, AY + tenDir.y * AR, INK, 1.1);
  axg.line(AX - xDir.x * BK, AY - xDir.y * BK, AX + xDir.x * (AR - 10), AY + xDir.y * (AR - 10))
    .stroke({ color: INK, width: 0.9 });
  arrow(axg, AX + xDir.x * (AR - 12), AY + xDir.y * (AR - 12), AX + xDir.x * AR, AY + xDir.y * AR, INK, 1.1);
  txt(axg, AX + tenDir.x * (AR + 5) - xDir.x * 15, AY + tenDir.y * (AR + 5) - xDir.y * 15,
    '+y', { italic: true, weight: 'bold', size: 13 });
  txt(axg, AX + xDir.x * (AR + 5) + tenDir.x * 15, AY + xDir.y * (AR + 5) + tenDir.y * 15,
    '+x', { italic: true, weight: 'bold', size: 13 });
  interactive(axg, 'Local axes: +y along the string toward the pivot, +x tangent to the arc',
    'Rotated coordinate frame',
    'Choosing axes along and perpendicular to the string is what makes the problem easy: the string force lies entirely on +y, so the only equation with a net force is the tangential one, ma = \u2212mg sin \u03b8.');

  updateReadoutPanel(thDeg, s, th);
}

function updateReadoutPanel(thDeg, sinv, rad) {
  var el = document.getElementById('readout');
  if (!el) return;
  var lin = document.getElementById('legendLinear');
  if (lin) lin.style.display = (state.model === 'exact') ? 'none' : 'flex';
  var err = Math.abs(sinv) < 1e-6 ? 0 : (Math.abs(rad) - Math.abs(sinv)) / Math.abs(sinv) * 100;
  var ft = Math.cos(rad) + (state.running ? (state.omega * state.omega) / G_OVER_L : 0);
  var lines = [
    '\u03b8      = ' + thDeg.toFixed(0) + '\u00b0  (' + rad.toFixed(3) + ' rad)',
    'sin \u03b8  = ' + sinv.toFixed(3),
    'F_tan  = ' + (-sinv).toFixed(3) + ' mg',
    'F_rad  = ' + (-Math.cos(rad)).toFixed(3) + ' mg',
    'F_T    = ' + ft.toFixed(3) + ' mg' + (state.running ? '  (swinging)' : '  (at rest)')
  ];
  if (state.model !== 'exact') {
    lines.push('\u03b8 (rad) = ' + Math.abs(rad).toFixed(3));
    lines.push('\u03b8 vs sin \u03b8 : +' + err.toFixed(1) + '%');
  }
  el.textContent = lines.join('\n');
}

/* ---------- interactions ---------- */
function update_thetaSlider(v) {
  stopSwing();
  state.theta = v;
  render();
}
function toggle_forceModel(v) { state.model = v; render(); }
function toggle_showConstruction(on) { state.constr = on; render(); }

function startSwing() {
  if (state.running) return;
  state.thRad = state.theta * Math.PI / 180;
  if (Math.abs(state.thRad) < 0.05) state.thRad = 25 * Math.PI / 180;
  state.omega = 0;
  state.running = true;
  document.getElementById('swingBtn').textContent = '\u23F8 Pause';
  lastT = 0;
  requestAnimationFrame(frame);
}
function stopSwing() {
  if (!state.running) return;
  state.running = false;
  state.omega = 0;
  document.getElementById('swingBtn').textContent = '\u25B6 Release the pendulum';
}
function trigger_swing() {
  if (state.running) { stopSwing(); render(); } else { startSwing(); }
}

var lastT = 0;
function frame(ts) {
  if (!state.running) return;
  if (!lastT) lastT = ts;
  var dt = Math.min(0.04, (ts - lastT) / 1000);
  lastT = ts;
  var n = 6, h = dt / n;
  for (var i = 0; i < n; i++) {
    state.omega += -G_OVER_L * Math.sin(state.thRad) * h;
    state.thRad += state.omega * h;
  }
  state.theta = state.thRad * 180 / Math.PI;
  document.getElementById('thetaSliderInput').value = Math.round(state.theta);
  document.getElementById('thetaSliderVal').value = Math.round(state.theta);
  render();
  requestAnimationFrame(frame);
}

/* ---------- demo steps ---------- */
var steps = [
  {
    t: 'The pendulum at rest',
    n: 'At \u03b8 = 0 the bob hangs on the dashed vertical. The weight w = mg points straight down along the string and is entirely balanced by the tension F_T \u2014 there is no tangential force, so nothing accelerates the bob.',
    theta: 0, model: 'exact', constr: false, swing: false
  },
  {
    t: 'Displace the bob and split the weight',
    n: 'At \u03b8 = 25\u00b0 the weight splits into \u2212mg cos \u03b8 along the string (opposed by tension) and \u2212mg sin \u03b8 tangent to the arc. Only the tangential piece is unbalanced, and it points back toward equilibrium along \u2212x. Tick \u201cShow weight-decomposition construction\u201d to see the parallelogram that builds those two arrows from w.',
    theta: 25, model: 'exact', constr: false, swing: false
  },
  {
    t: 'Push to a large angle',
    n: 'At 60\u00b0 the tangential arrow is long and the radial arrow has shrunk. The restoring force grows with displacement \u2014 but not in proportion to it, because it follows sin \u03b8, not \u03b8.',
    theta: 60, model: 'exact', constr: false, swing: false
  },
  {
    t: 'Sign flip through equilibrium',
    n: 'Released from 25\u00b0, the bob swings. Each time it crosses the dashed vertical the tangential arrow reverses direction, so the force always points back toward the centre \u2014 that is what sustains the oscillation. Watch F_T in the numbers: it peaks at the bottom, where mv\u00b2/L is largest.',
    theta: 25, model: 'exact', constr: false, swing: true
  },
  {
    t: 'The small-angle approximation',
    n: 'In compare view at 12\u00b0 the orange \u2212mg\u03b8 arrow nearly coincides with the crimson \u2212mg sin \u03b8 arrow: the restoring force is proportional to displacement, so the pendulum is a simple harmonic oscillator with T = 2\u03c0\u221a(L/g).',
    theta: 12, model: 'both', constr: false, swing: false
  },
  {
    t: 'Where the approximation breaks',
    n: 'At 50\u00b0 the two arrows visibly disagree \u2014 the true restoring force is weaker than the linear estimate (see the percentage error), the motion is no longer simple harmonic, and the real period lengthens.',
    theta: 50, model: 'both', constr: false, swing: false
  }
];
var curStep = 1;

function applyStep(i) {
  curStep = (i + steps.length) % steps.length;
  var st = steps[curStep];
  stopSwing();
  document.getElementById('thetaSliderInput').value = st.theta;
  document.getElementById('thetaSliderVal').value = st.theta;
  state.theta = st.theta;
  document.getElementById('forceModelInput').value = st.model;
  state.model = st.model;
  document.getElementById('showConstructionInput').checked = st.constr;
  state.constr = st.constr;
  document.getElementById('demoTitle').textContent = st.t;
  document.getElementById('demoNarration').textContent = st.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' / ' + steps.length;
  if (st.swing) startSwing(); else render();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

/* ---------- boot: default view matches the source figure (\u03b8 = 25\u00b0) ---------- */
applyStep(1);
render();
window.__markRendered();
// @FIGURE_CODE_END

